const MANIFEST = {
  "type": "Data.AnimatedStatistics",
  "description": "Scroll-triggered number counting with staggered reveals and sophisticated data visualization",
  "editorElement": {
    "selector": ".animated-statistics",
    "displayName": "Animated Statistics",
    "archetype": "container",
    "data": {
      "stats": {
        "dataType": "text",
        "displayName": "Statistics (value|label|suffix)",
        "defaultValue": "98|Customer Satisfaction|%,2.5|Revenue Growth|M,150|Active Projects|+,12|Years Experience|+",
        "group": "Content",
        "description": "Format: value|label|suffix, separated by commas"
      },
      "headline": {
        "dataType": "text",
        "displayName": "Headline",
        "defaultValue": "Results That Speak",
        "group": "Content"
      },
      "subheadline": {
        "dataType": "text",
        "displayName": "Subheadline",
        "defaultValue": "Delivering measurable impact across every dimension",
        "group": "Content"
      },
      "countDuration": {
        "dataType": "select",
        "displayName": "Count Duration (ms)",
        "defaultValue": "2000",
        "options": ["1000", "1500", "2000", "2500", "3000"],
        "group": "Animation"
      },
      "staggerDelay": {
        "dataType": "select",
        "displayName": "Stagger Delay (ms)",
        "defaultValue": "150",
        "options": ["100", "150", "200", "250", "300"],
        "group": "Animation"
      },
      "easingFunction": {
        "dataType": "select",
        "displayName": "Easing Function",
        "defaultValue": "easeOutExpo",
        "options": ["linear", "easeOutQuad", "easeOutCubic", "easeOutExpo", "easeOutElastic"],
        "group": "Animation"
      },
      "triggerMode": {
        "dataType": "select",
        "displayName": "Trigger Mode",
        "defaultValue": "scroll",
        "options": ["entrance", "scroll", "manual"],
        "group": "Animation"
      },
      "scrollThreshold": {
        "dataType": "select",
        "displayName": "Scroll Threshold",
        "defaultValue": "0.3",
        "options": ["0.1", "0.2", "0.3", "0.5", "0.7"],
        "group": "Animation"
      },
      "showProgressBars": {
        "dataType": "booleanValue",
        "displayName": "Show Progress Bars",
        "defaultValue": "true",
        "group": "Content"
      },
      "showReplayButton": {
        "dataType": "booleanValue",
        "displayName": "Show Replay Button",
        "defaultValue": "true",
        "group": "Content"
      },
      "gridColumns": {
        "dataType": "select",
        "displayName": "Grid Columns",
        "defaultValue": "4",
        "options": ["2", "3", "4"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "cardBackground": {
        "dataType": "color",
        "displayName": "Card Background",
        "defaultValue": "#27272A",
        "group": "Colors"
      },
      "cardBorder": {
        "dataType": "color",
        "displayName": "Card Border",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "numberColor": {
        "dataType": "color",
        "displayName": "Number Color",
        "defaultValue": "#FAFAFA",
        "group": "Colors"
      },
      "labelColor": {
        "dataType": "color",
        "displayName": "Label Color",
        "defaultValue": "#A1A1AA",
        "group": "Colors"
      },
      "progressBackground": {
        "dataType": "color",
        "displayName": "Progress Background",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "progressFill": {
        "dataType": "color",
        "displayName": "Progress Fill",
        "defaultValue": "#71717A",
        "group": "Colors"
      },
      "headlineColor": {
        "dataType": "color",
        "displayName": "Headline Color",
        "defaultValue": "#FAFAFA",
        "group": "Colors"
      },
      "subheadlineColor": {
        "dataType": "color",
        "displayName": "Subheadline Color",
        "defaultValue": "#71717A",
        "group": "Colors"
      },
      "numberFontSize": {
        "dataType": "number",
        "displayName": "Number Font Size (px)",
        "defaultValue": 56,
        "group": "Typography"
      },
      "headlineFontSize": {
        "dataType": "number",
        "displayName": "Headline Font Size (px)",
        "defaultValue": 40,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Number Font Weight",
        "defaultValue": "300",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "letterSpacing": {
        "dataType": "select",
        "displayName": "Letter Spacing",
        "defaultValue": "0.025em",
        "options": ["0em", "0.025em", "0.05em"],
        "group": "Typography"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const statsString = config?.stats || '98|Customer Satisfaction|%,2.5|Revenue Growth|M,150|Active Projects|+,12|Years Experience|+';
  const headline = config?.headline || 'Results That Speak';
  const subheadline = config?.subheadline || 'Delivering measurable impact across every dimension';
  const countDuration = parseInt(config?.countDuration || '2000');
  const staggerDelay = parseInt(config?.staggerDelay || '150');
  const easingFunction = config?.easingFunction || 'easeOutExpo';
  const triggerMode = config?.triggerMode || 'scroll';
  const scrollThreshold = parseFloat(config?.scrollThreshold || '0.3');
  const showProgressBars = config?.showProgressBars !== false;
  const showReplayButton = config?.showReplayButton !== false;
  const gridColumns = parseInt(config?.gridColumns || '4');
  const backgroundColor = config?.backgroundColor || '#18181B';
  const cardBackground = config?.cardBackground || '#27272A';
  const cardBorder = config?.cardBorder || '#3F3F46';
  const numberColor = config?.numberColor || '#FAFAFA';
  const labelColor = config?.labelColor || '#A1A1AA';
  const progressBackground = config?.progressBackground || '#3F3F46';
  const progressFill = config?.progressFill || '#71717A';
  const headlineColor = config?.headlineColor || '#FAFAFA';
  const subheadlineColor = config?.subheadlineColor || '#71717A';
  const numberFontSize = parseInt(config?.numberFontSize || '56');
  const headlineFontSize = parseInt(config?.headlineFontSize || '40');
  const fontWeight = config?.fontWeight || '300';
  const letterSpacing = config?.letterSpacing || '0.025em';

  const stats = React.useMemo(() => {
    return statsString.split(',').map(stat => {
      const [value, label, suffix] = stat.split('|').map(s => s.trim());
      return {
        value: parseFloat(value) || 0,
        label: label || '',
        suffix: suffix || '',
        isDecimal: value.includes('.')
      };
    }).filter(s => s.label);
  }, [statsString]);

  const containerRef = React.useRef(null);
  const [displayValues, setDisplayValues] = React.useState(stats.map(() => 0));
  const [progressWidths, setProgressWidths] = React.useState(stats.map(() => 0));
  const [hasAnimated, setHasAnimated] = React.useState(false);
  const [cardVisible, setCardVisible] = React.useState(stats.map(() => false));
  const [isButtonHovered, setIsButtonHovered] = React.useState(false);
  const animationRef = React.useRef(null);

  const prefersReducedMotion = React.useMemo(() => {
    return typeof window !== 'undefined'
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
      : false;
  }, []);

  const easingFunctions = {
    linear: (t) => t,
    easeOutQuad: (t) => t * (2 - t),
    easeOutCubic: (t) => 1 - Math.pow(1 - t, 3),
    easeOutExpo: (t) => t === 1 ? 1 : 1 - Math.pow(2, -10 * t),
    easeOutElastic: (t) => {
      const c4 = (2 * Math.PI) / 3;
      return t === 0 ? 0 : t === 1 ? 1 : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1;
    }
  };

  const animate = React.useCallback(() => {
    if (prefersReducedMotion) {
      setDisplayValues(stats.map(s => s.value));
      setProgressWidths(stats.map(s => Math.min(100, s.value)));
      setCardVisible(stats.map(() => true));
      setHasAnimated(true);
      return;
    }

    stats.forEach((_, index) => {
      setTimeout(() => {
        setCardVisible(prev => {
          const newVisible = [...prev];
          newVisible[index] = true;
          return newVisible;
        });
      }, index * staggerDelay);
    });

    const startTime = Date.now();
    const easing = easingFunctions[easingFunction] || easingFunctions.easeOutExpo;

    const updateValues = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(1, elapsed / countDuration);
      const easedProgress = easing(progress);

      setDisplayValues(stats.map((stat) => {
        const current = stat.value * easedProgress;
        return stat.isDecimal ? Math.round(current * 10) / 10 : Math.round(current);
      }));

      setProgressWidths(stats.map((stat) => {
        const targetProgress = Math.min(100, stat.value);
        return targetProgress * easedProgress;
      }));

      if (progress < 1) {
        animationRef.current = requestAnimationFrame(updateValues);
      } else {
        setDisplayValues(stats.map(s => s.value));
        setHasAnimated(true);
      }
    };

    animationRef.current = requestAnimationFrame(updateValues);
  }, [stats, countDuration, staggerDelay, easingFunction, prefersReducedMotion]);

  const handleReplay = React.useCallback(() => {
    if (animationRef.current) {
      cancelAnimationFrame(animationRef.current);
    }
    setHasAnimated(false);
    setDisplayValues(stats.map(() => 0));
    setProgressWidths(stats.map(() => 0));
    setCardVisible(stats.map(() => false));
    setTimeout(animate, 50);
  }, [animate, stats]);

  React.useEffect(() => {
    if (triggerMode === 'manual') return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            if (triggerMode === 'entrance' && hasAnimated) return;
            if (triggerMode === 'scroll') {
              setHasAnimated(false);
              setDisplayValues(stats.map(() => 0));
              setProgressWidths(stats.map(() => 0));
              setCardVisible(stats.map(() => false));
            }
            setTimeout(animate, 100);
          }
        });
      },
      { threshold: scrollThreshold }
    );

    const container = containerRef.current;
    if (container) observer.observe(container);
    return () => observer.disconnect();
  }, [triggerMode, scrollThreshold, hasAnimated, animate, stats]);

  React.useEffect(() => {
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  const formatNumber = (num, isDecimal) => {
    if (isDecimal) {
      return num.toFixed(1);
    }
    return Math.round(num).toLocaleString();
  };

  return (
    <div
      ref={containerRef}
      className="animated-statistics"
      style={{
        position: 'relative',
        width: '100%',
        backgroundColor: backgroundColor,
        padding: '80px 40px',
        boxSizing: 'border-box'
      }}
    >
      <div
        style={{
          maxWidth: '1200px',
          margin: '0 auto'
        }}
      >
        <div
          style={{
            textAlign: 'center',
            marginBottom: '64px'
          }}
        >
          <h2
            style={{
              fontSize: `clamp(28px, ${headlineFontSize}px, 5vw)`,
              fontWeight: '300',
              letterSpacing: '0.05em',
              color: headlineColor,
              margin: '0 0 16px 0',
              fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
            }}
          >
            {headline}
          </h2>
          <p
            style={{
              fontSize: '16px',
              color: subheadlineColor,
              margin: 0,
              fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
            }}
          >
            {subheadline}
          </p>
        </div>

        <div
          style={{
            display: 'grid',
            gridTemplateColumns: `repeat(${gridColumns}, 1fr)`,
            gap: '24px'
          }}
        >
          {stats.map((stat, index) => (
            <div
              key={index}
              style={{
                backgroundColor: cardBackground,
                border: `1px solid ${cardBorder}`,
                borderRadius: '8px',
                padding: '32px',
                opacity: cardVisible[index] ? 1 : 0,
                transform: cardVisible[index] ? 'translateY(0)' : 'translateY(20px)',
                transition: prefersReducedMotion ? 'none' : 'all 500ms cubic-bezier(0.22, 1, 0.36, 1)'
              }}
            >
              <div
                style={{
                  display: 'flex',
                  alignItems: 'baseline',
                  marginBottom: '12px'
                }}
              >
                <span
                  style={{
                    fontSize: `clamp(32px, ${numberFontSize}px, 8vw)`,
                    fontWeight: fontWeight,
                    letterSpacing: letterSpacing,
                    color: numberColor,
                    fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
                    lineHeight: 1,
                    fontVariantNumeric: 'tabular-nums'
                  }}
                >
                  {formatNumber(displayValues[index], stat.isDecimal)}
                </span>
                <span
                  style={{
                    fontSize: '24px',
                    fontWeight: '400',
                    color: labelColor,
                    marginLeft: '4px',
                    fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
                  }}
                >
                  {stat.suffix}
                </span>
              </div>

              <p
                style={{
                  fontSize: '14px',
                  color: labelColor,
                  margin: '0 0 16px 0',
                  fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
                  letterSpacing: '0.025em'
                }}
              >
                {stat.label}
              </p>

              {showProgressBars && (
                <div
                  style={{
                    width: '100%',
                    height: '4px',
                    backgroundColor: progressBackground,
                    borderRadius: '2px',
                    overflow: 'hidden'
                  }}
                >
                  <div
                    style={{
                      width: `${progressWidths[index]}%`,
                      height: '100%',
                      backgroundColor: progressFill,
                      borderRadius: '2px',
                      transition: prefersReducedMotion ? 'none' : 'width 100ms linear'
                    }}
                  />
                </div>
              )}
            </div>
          ))}
        </div>

        {showReplayButton && (
          <div
            style={{
              display: 'flex',
              justifyContent: 'center',
              marginTop: '48px'
            }}
          >
            <button
              onClick={handleReplay}
              onMouseEnter={() => setIsButtonHovered(true)}
              onMouseLeave={() => setIsButtonHovered(false)}
              style={{
                padding: '12px 28px',
                backgroundColor: 'transparent',
                border: `1px solid ${cardBorder}`,
                borderRadius: '4px',
                color: isButtonHovered ? numberColor : labelColor,
                fontSize: '13px',
                fontWeight: '400',
                letterSpacing: '0.1em',
                textTransform: 'uppercase',
                cursor: 'pointer',
                transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out',
                fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
                transform: isButtonHovered ? 'translateY(-2px)' : 'translateY(0)'
              }}
            >
              Replay Animation
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

interactive-progressring:
const MANIFEST = {
  "type": "Interactive.ProgressRing",
  "description": "Circular progress indicator with animated percentage counter",
  "editorElement": {
    "selector": ".progress-ring",
    "displayName": "Progress Ring",
    "archetype": "container",
    "data": {
      "progress": {
        "dataType": "select",
        "displayName": "Progress (%)",
        "defaultValue": "75",
        "options": ["0", "25", "50", "75", "85", "100"],
        "group": "Content"
      },
      "label": {
        "dataType": "text",
        "displayName": "Label",
        "defaultValue": "Complete",
        "group": "Content"
      },
      "showPercentage": {
        "dataType": "booleanValue",
        "displayName": "Show Percentage",
        "defaultValue": true,
        "group": "Content"
      },
      "animationDuration": {
        "dataType": "select",
        "displayName": "Animation Duration (ms)",
        "defaultValue": "1500",
        "options": ["1000", "1500", "2000", "2500"],
        "group": "Animation"
      },
      "animateOnView": {
        "dataType": "booleanValue",
        "displayName": "Animate On Scroll Into View",
        "defaultValue": true,
        "group": "Animation"
      },
      "size": {
        "dataType": "select",
        "displayName": "Ring Size (px)",
        "defaultValue": "180",
        "options": ["120", "150", "180", "200", "240"],
        "group": "Layout"
      },
      "strokeWidth": {
        "dataType": "select",
        "displayName": "Stroke Width",
        "defaultValue": "12",
        "options": ["8", "10", "12", "14", "16"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "trackColor": {
        "dataType": "color",
        "displayName": "Track Color",
        "defaultValue": "#E4E4E7",
        "group": "Colors"
      },
      "progressColor": {
        "dataType": "color",
        "displayName": "Progress Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "labelColor": {
        "dataType": "color",
        "displayName": "Label Color",
        "defaultValue": "#71717A",
        "group": "Colors"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Font Size (px)",
        "defaultValue": 32,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Font Weight",
        "defaultValue": "500",
        "options": ["300", "400", "500"],
        "group": "Typography"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const [animatedProgress, setAnimatedProgress] = React.useState(0);
  const [hasAnimated, setHasAnimated] = React.useState(false);
  const containerRef = React.useRef(null);
  const animationFrameRef = React.useRef(null);

  // Config values
  const progress = parseInt(config?.progress || "75");
  const label = config?.label || "Complete";
  const showPercentage = config?.showPercentage !== false;
  const animationDuration = parseInt(config?.animationDuration || "1500");
  const animateOnView = config?.animateOnView !== false;
  const size = parseInt(config?.size || "180");
  const strokeWidth = parseInt(config?.strokeWidth || "12");
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const trackColor = config?.trackColor || "#E4E4E7";
  const progressColor = config?.progressColor || "#18181B";
  const textColor = config?.textColor || "#18181B";
  const labelColor = config?.labelColor || "#71717A";
  const fontSize = config?.fontSize || 32;
  const fontWeight = config?.fontWeight || "500";

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  // Easing function (ease-out cubic)
  const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

  const animateProgress = React.useCallback(() => {
    const startTime = Date.now();
    const startValue = 0;
    const endValue = progress;

    const animate = () => {
      const elapsed = Date.now() - startTime;
      const progressRatio = Math.min(elapsed / animationDuration, 1);
      const easedProgress = easeOutCubic(progressRatio);
      const currentValue = startValue + (endValue - startValue) * easedProgress;

      setAnimatedProgress(Math.round(currentValue));

      if (progressRatio < 1) {
        animationFrameRef.current = requestAnimationFrame(animate);
      }
    };

    animate();
  }, [progress, animationDuration]);

  // Intersection Observer for scroll animation
  React.useEffect(() => {
    if (!animateOnView || hasAnimated || prefersReducedMotion) {
      if (!animateOnView || prefersReducedMotion) {
        setAnimatedProgress(progress);
      }
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting && !hasAnimated) {
            setHasAnimated(true);
            animateProgress();
          }
        });
      },
      { threshold: 0.3 }
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => {
      observer.disconnect();
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [animateOnView, hasAnimated, animateProgress, prefersReducedMotion, progress]);

  // Immediate animation if not scroll-triggered
  React.useEffect(() => {
    if (!animateOnView && !prefersReducedMotion) {
      animateProgress();
    } else if (prefersReducedMotion) {
      setAnimatedProgress(progress);
    }
  }, [animateOnView, animateProgress, prefersReducedMotion, progress]);

  // SVG calculations
  const center = size / 2;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const progressOffset = circumference - (animatedProgress / 100) * circumference;

  const containerStyle = {
    display: 'inline-flex',
    flexDirection: 'column',
    alignItems: 'center',
    gap: '16px',
    backgroundColor: backgroundColor,
    padding: '24px'
  };

  const svgStyle = {
    transform: 'rotate(-90deg)',
    overflow: 'visible'
  };

  const trackStyle = {
    fill: 'none',
    stroke: trackColor,
    strokeWidth: strokeWidth
  };

  const progressStyle = {
    fill: 'none',
    stroke: progressColor,
    strokeWidth: strokeWidth,
    strokeDasharray: circumference,
    strokeDashoffset: prefersReducedMotion ? circumference - (progress / 100) * circumference : progressOffset,
    strokeLinecap: 'round',
    transition: prefersReducedMotion ? 'none' : 'stroke-dashoffset 0.3s ease',
    willChange: 'stroke-dashoffset'
  };

  const textContainerStyle = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    textAlign: 'center'
  };

  const percentageStyle = {
    fontSize: `${fontSize}px`,
    fontWeight: fontWeight,
    color: textColor,
    lineHeight: 1
  };

  const labelStyle = {
    fontSize: `${fontSize * 0.4}px`,
    fontWeight: '400',
    color: labelColor,
    marginTop: '8px',
    textTransform: 'uppercase',
    letterSpacing: '0.1em'
  };

  return (
    <div 
      ref={containerRef}
      className="progress-ring"
      style={containerStyle}
      role="progressbar"
      aria-valuenow={animatedProgress}
      aria-valuemin="0"
      aria-valuemax="100"
      aria-label={`${label}: ${animatedProgress}% complete`}
    >
      <div style={{ position: 'relative', width: size, height: size }}>
        <svg width={size} height={size} style={svgStyle}>
          {/* Track */}
          <circle
            cx={center}
            cy={center}
            r={radius}
            style={trackStyle}
          />
          {/* Progress */}
          <circle
            cx={center}
            cy={center}
            r={radius}
            style={progressStyle}
          />
        </svg>

        {/* Text */}
        <div style={textContainerStyle}>
          {showPercentage && (
            <span style={percentageStyle}>{animatedProgress}%</span>
          )}
          {label && <span style={labelStyle}>{label}</span>}
        </div>
      </div>
    </div>
  );
}

data-skillwheel:
const MANIFEST = {
  "type": "Data.SkillWheel",
  "description": "Circular skill wheel with gradient fills, staggered animations, and animated percentage counter",
  "editorElement": {
    "selector": ".skill-wheel",
    "displayName": "Skill Wheel",
    "archetype": "container",
    "data": {
      "radius": {
        "dataType": "select",
        "displayName": "Wheel Radius",
        "defaultValue": "180",
        "options": ["140", "160", "180", "200", "220"],
        "group": "Layout"
      },
      "segmentGap": {
        "dataType": "select",
        "displayName": "Segment Gap",
        "defaultValue": "4",
        "options": ["2", "3", "4", "5", "6"],
        "group": "Layout"
      },
      "strokeWidth": {
        "dataType": "select",
        "displayName": "Stroke Width",
        "defaultValue": "28",
        "options": ["20", "24", "28", "32", "36"],
        "group": "Layout"
      },
      "triggerMode": {
        "dataType": "select",
        "displayName": "Trigger Mode",
        "defaultValue": "scroll",
        "options": ["scroll", "immediate"],
        "group": "Animation"
      },
