                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            fontSize: '10px',
                            color: '#FFFFFF',
                            fontWeight: '500',
                            opacity: seatStatus[seatId] === 'occupied' ? 0.5 : 1
                          }}
                          onMouseEnter={(e) => {
                            if (seatStatus[seatId] !== 'occupied') {
                              e.currentTarget.style.transform = 'scale(1.1)';
                            }
                          }}
