function Component({ config = {} }) {
  const label = config?.label || "TOTAL PROJECTS";
  const startValue = parseFloat(config?.startValue || "0");
  const endValue = parseFloat(config?.endValue || "2547");
  const prefix = config?.prefix || "";
  const suffix = config?.suffix || "+";
  const description = config?.description || "Successfully delivered projects worldwide";
  const showReplayButton = config?.showReplayButton !== false;
  const triggerMode = config?.triggerMode || "scroll";
  const duration = parseInt(config?.duration || "2000");
  const easingFunction = config?.easingFunction || "easeOutQuart";
  const decimalPlaces = parseInt(config?.decimalPlaces || "0");
  const useThousandSeparator = config?.useThousandSeparator !== false;
  const counterFontSize = parseInt(config?.counterFontSize || "72");
  const labelFontSize = parseInt(config?.labelFontSize || "14");
  const descriptionFontSize = parseInt(config?.descriptionFontSize || "16");
  const fontWeight = config?.fontWeight || "500";
  const letterSpacing = config?.letterSpacing || "0.1em";
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const counterColor = config?.counterColor || "#212529";
  const labelColor = config?.labelColor || "#6C757D";
  const descriptionColor = config?.descriptionColor || "#6C757D";
  const accentColor = config?.accentColor || "#212529";

  const [currentValue, setCurrentValue] = React.useState(startValue);
  const [isAnimating, setIsAnimating] = React.useState(false);
  const [hasAnimated, setHasAnimated] = React.useState(false);
  const [progress, setProgress] = React.useState(0);
  const containerRef = React.useRef(null);
  const animationRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  // Easing functions
  const easingFunctions = {
    linear: (t) => t,
    easeOutQuad: (t) => t * (2 - t),
    easeOutCubic: (t) => (--t) * t * t + 1,
    easeOutQuart: (t) => 1 - (--t) * t * t * t,
    easeInOutCubic: (t) => t < 0.5 ? 4 * t * t * t : (t - 1) * (2 * t - 2) * (2 * t - 2) + 1,
    elastic: (t) => {
      if (t === 0 || t === 1) return t;
      const p = 0.3;
      const s = p / 4;
      return Math.pow(2, -10 * t) * Math.sin((t - s) * (2 * Math.PI) / p) + 1;
    }
  };

  const easing = easingFunctions[easingFunction] || easingFunctions.easeOutQuart;

  const formatNumber = (num) => {
    let formatted = num.toFixed(decimalPlaces);

    if (useThousandSeparator) {
      const parts = formatted.split('.');
      parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
      formatted = parts.join('.');
    }

    return `${prefix}${formatted}${suffix}`;
  };

  const animate = React.useCallback(() => {
    if (isAnimating || prefersReducedMotion) {
      if (prefersReducedMotion) {
        setCurrentValue(endValue);
        setProgress(100);
      }
      return;
    }

    setIsAnimating(true);
    setCurrentValue(startValue);
    setProgress(0);

    const startTime = performance.now();

    const step = (currentTime) => {
      const elapsed = currentTime - startTime;
      const progressRatio = Math.min(elapsed / duration, 1);
      const easedProgress = easing(progressRatio);

      const newValue = startValue + (endValue - startValue) * easedProgress;
      setCurrentValue(newValue);
      setProgress(progressRatio * 100);

      if (progressRatio < 1) {
        animationRef.current = requestAnimationFrame(step);
      } else {
        setIsAnimating(false);
        setHasAnimated(true);
      }
    };

    animationRef.current = requestAnimationFrame(step);
  }, [startValue, endValue, duration, easingFunction, isAnimating, prefersReducedMotion]);

  React.useEffect(() => {
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  React.useEffect(() => {
    if (triggerMode === 'immediate') {
      animate();
      return;
    }

    if (triggerMode === 'scroll' && containerRef.current) {
      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting && !hasAnimated) {
              animate();
            }
          });
        },
        { threshold: 0.3 }
      );

      observer.observe(containerRef.current);
      return () => observer.disconnect();
    }
  }, [triggerMode, hasAnimated, animate]);

  const handleReplay = () => {
    if (animationRef.current) {
      cancelAnimationFrame(animationRef.current);
    }
    setIsAnimating(false);
    setHasAnimated(false);
    setTimeout(() => animate(), 50);
  };

  return (
    <div className="animated-counter" style={{
      minHeight: '100vh',
      width: '100%',
      backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '3rem 1.5rem',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div
        ref={containerRef}
        style={{
          maxWidth: '600px',
          width: '100%',
          textAlign: 'center',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: '2rem'
        }}
      >
        {/* Label */}
        <div style={{
          fontSize: `${labelFontSize}px`,
          fontWeight: '400',
          letterSpacing,
          color: labelColor,
          textTransform: 'uppercase'
        }}>
          {label}
        </div>

        {/* Counter */}
        <div style={{
          fontSize: `clamp(${counterFontSize * 0.5}px, ${counterFontSize / 16}rem + 3vw, ${counterFontSize}px)`,
          fontWeight,
          color: counterColor,
          lineHeight: 1,
          fontVariantNumeric: 'tabular-nums',
          letterSpacing: '-0.02em'
        }}>
          {formatNumber(currentValue)}
        </div>

        {/* Progress Bar */}
        <div style={{
          width: '100%',
          height: '2px',
          backgroundColor: '#E9ECEF',
          borderRadius: '2px',
          overflow: 'hidden',
          position: 'relative'
        }}>
          <div style={{
            height: '100%',
            backgroundColor: accentColor,
            width: `${progress}%`,
            transition: prefersReducedMotion ? 'none' : 'width 50ms linear',
            borderRadius: '2px'
          }} />
        </div>

        {/* Description */}
        <p style={{
          fontSize: `${descriptionFontSize}px`,
          fontWeight: '400',
          color: descriptionColor,
          lineHeight: 1.6,
          margin: 0,
          maxWidth: '450px'
        }}>
          {description}
        </p>

        {/* Replay Button */}
        {showReplayButton && (
          <button
            onClick={handleReplay}
            disabled={isAnimating}
            style={{
              marginTop: '1rem',
              padding: '0.75rem 1.5rem',
              fontSize: '0.875rem',
              fontWeight: '400',
              fontFamily: 'inherit',
              color: isAnimating ? '#CED4DA' : accentColor,
              backgroundColor: 'transparent',
              border: `1px solid ${isAnimating ? '#E9ECEF' : accentColor}`,
              borderRadius: '6px',
              cursor: isAnimating ? 'not-allowed' : 'pointer',
              transition: 'all 200ms ease-out',
              letterSpacing: '0.025em'
            }}
            onMouseEnter={(e) => {
              if (!isAnimating) {
                e.currentTarget.style.backgroundColor = accentColor;
                e.currentTarget.style.color = backgroundColor;
              }
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent';
              e.currentTarget.style.color = accentColor;
            }}
          >
            {isAnimating ? 'Counting...' : 'Replay Animation'}
          </button>
        )}

        {/* Stats Grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: '2rem',
          marginTop: '2rem',
          width: '100%',
          paddingTop: '2rem',
          borderTop: '1px solid #E9ECEF'
        }}>
          <div style={{ textAlign: 'center' }}>
            <div style={{ fontSize: '0.75rem', color: labelColor, marginBottom: '0.5rem', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              Duration
            </div>
            <div style={{ fontSize: '1rem', fontWeight: '500', color: counterColor }}>
              {(duration / 1000).toFixed(1)}s
            </div>
          </div>
          <div style={{ textAlign: 'center' }}>
            <div style={{ fontSize: '0.75rem', color: labelColor, marginBottom: '0.5rem', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              Easing
            </div>
            <div style={{ fontSize: '1rem', fontWeight: '500', color: counterColor }}>
              {easingFunction.replace('ease', '').replace('Out', ' Out').replace('In', ' In')}
            </div>
          </div>
