              border: `2px solid ${tier.isRecommended ? recommendedBorderColor : borderColor}`,
              borderRadius: cardBorderRadius,
              padding: cardPadding,
              position: 'relative',
              display: 'flex',
              flexDirection: 'column',
              transform: tier.isRecommended && !prefersReducedMotion ? 'scale(1.05)' : 'scale(1)',
              boxShadow: tier.isRecommended ? '0 4px 12px rgba(0,0,0,0.08)' : '0 1px 3px rgba(0,0,0,0.06)',
              transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
            }}
          >
            {tier.isRecommended && (
              <div style={{
                position: 'absolute',
                top: '-12px',
                left: '50%',
                transform: 'translateX(-50%)',
                backgroundColor: badgeBackgroundColor,
                color: badgeTextColor,
                padding: '4px 16px',
                borderRadius: '4px',
                fontSize: '11px',
                fontWeight: '500',
                letterSpacing: '0.05em'
              }}>
                {tier.badge}
              </div>
            )}

            <div style={{
              marginBottom: '24px',
              paddingBottom: '24px',
              borderBottom: `1px solid ${borderColor}`
            }}>
              <h3 style={{
                margin: '0 0 16px 0',
                fontSize: `${tierNameSize}px`,
                fontWeight: '500',
                color: textColor,
                letterSpacing: '-0.01em'
              }}>
                {tier.name}
              </h3>

              <div style={{
                display: 'flex',
                alignItems: 'baseline',
                gap: '4px'
              }}>
                <span style={{
                  fontSize: `${priceSize}px`,
                  fontWeight: '300',
                  color: textColor,
                  lineHeight: '1'
                }}>
                  {tier.price}
                </span>
                {tier.period && (
                  <span style={{
                    fontSize: `${featureSize}px`,
                    color: secondaryTextColor,
                    fontWeight
                  }}>
                    {tier.period}
                  </span>
                )}
              </div>
            </div>

            <ul style={{
              listStyle: 'none',
              padding: 0,
              margin: '0 0 32px 0',
              flex: 1
            }}>
              {tier.features.map((feature, fIndex) => (
                <li
                  key={fIndex}
                  style={{
                    display: 'flex',
                    alignItems: 'flex-start',
                    gap: '12px',
                    marginBottom: '12px',
                    fontSize: `${featureSize}px`,
                    color: textColor,
                    fontWeight,
                    lineHeight: '1.6'
                  }}
                >
                  <svg
                    width="20"
                    height="20"
                    viewBox="0 0 20 20"
                    fill="none"
                    style={{
                      flexShrink: 0,
                      marginTop: '2px'
                    }}
                  >
                    <circle cx="10" cy="10" r="10" fill={checkmarkColor} fillOpacity="0.1" />
                    <path
                      d="M6 10l2.5 2.5L14 7"
                      stroke={checkmarkColor}
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                  <span>{feature}</span>
                </li>
              ))}
            </ul>

            <button
              style={{
                width: '100%',
                padding: '14px 24px',
                backgroundColor: buttonBackgroundColor,
                color: buttonTextColor,
                border: 'none',
                borderRadius: '6px',
                fontSize: '15px',
                fontWeight: '500',
                cursor: 'pointer',
                transition: prefersReducedMotion ? 'none' : 'background-color 200ms ease-out',
                fontFamily
              }}
              onMouseEnter={(e) => {
                if (!prefersReducedMotion) {
                  e.currentTarget.style.backgroundColor = buttonHoverColor;
                }
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.backgroundColor = buttonBackgroundColor;
              }}
            >
              {tier.buttonText}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

