  const metricPrefix = config?.metricPrefix || "$";
  const metricSuffix = config?.metricSuffix || "";
  const trendValue = config?.trendValue || "+12.5";
  const trendLabel = config?.trendLabel || "vs last month";
  const sparklineDataRaw = config?.sparklineData || "45,52,48,61,55,67,58,72,65,78,71,85";
  const animateOnScroll = config?.animateOnScroll !== false;

  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const metricBackgroundColor = config?.metricBackgroundColor || "#F8F9FA";
  const borderColor = config?.borderColor || "#E9ECEF";
  const labelColor = config?.labelColor || "#495057";
  const valueColor = config?.valueColor || "#212529";
  const trendColor = config?.trendColor || "#6C757D";
  const sparklineColor = config?.sparklineColor || "#495057";
  const sparklineBackgroundColor = config?.sparklineBackgroundColor || "#F1F3F5";
  const positiveTrendColor = config?.positiveTrendColor || "#495057";
  const negativeTrendColor = config?.negativeTrendColor || "#343A40";

  const labelFontSize = config?.labelFontSize || 14;
  const valueFontSize = config?.valueFontSize || 36;
  const trendFontSize = config?.trendFontSize || 13;
  const valueFontWeight = config?.valueFontWeight || "500";

