      const x = (index / (sparklineData.length - 1)) * (width - padding * 2) + padding;
      const y = height - ((value - minValue) / valueRange) * (height - padding * 2) - padding;
      return `${x},${y}`;
    });

    return `M ${points.join(' L ')}`;
  };

  const sparklinePath = generateSparklinePath();
