                d="M7 11L7 3M7 11L4 8M7 11L10 8"
                stroke={trendIndicatorColor}
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            )}
          </svg>

          {/* Trend Text */}
          <div
            style={{
              fontSize: `${trendFontSize}px`,
              fontWeight: '400',
              color: trendColor
            }}
          >
            <span style={{ fontWeight: '500', marginRight: '4px' }}>{trendValue}%</span>
            <span>{trendLabel}</span>
          </div>
        </div>
      </div>

      {/* Sparkline Chart */}
      <div
        style={{
          backgroundColor: sparklineBackgroundColor,
          borderRadius: '6px',
          padding: '12px',
          overflow: 'hidden'
        }}
      >
        <svg
          width="100%"
          height={sparklineHeight}
          viewBox={`0 0 200 ${sparklineHeight}`}
          preserveAspectRatio="none"
          style={{
            display: 'block'
          }}
        >
          <path
            d={sparklinePath}
            fill="none"
            stroke={sparklineColor}
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{
              strokeDasharray: hasAnimated ? 'none' : pathLength,
              strokeDashoffset: hasAnimated ? 0 : pathLength,
              animation: hasAnimated ? `drawSparkline ${sparklineAnimationDuration}ms ease-out forwards` : 'none'
            }}
          />
        </svg>
      </div>

      {/* CSS Animation */}
      <style>{`
        @keyframes drawSparkline {
          from {
            stroke-dashoffset: ${pathLength};
          }
          to {
            stroke-dashoffset: 0;
          }
        }
      `}</style>
    </div>
  );
}

