// Component #9: Advanced Data Dashboard
const MANIFEST = {
  "type": "Analytics.DataDashboard",
  "description": "Real-time animated data visualization dashboard with counting metrics, interactive charts, and progress rings",
  "editorElement": {
    "selector": ".data-dashboard",
    "displayName": "Data Dashboard",
    "archetype": "container",
    "data": {
      "metric1Label": { "dataType": "text", "displayName": "Metric 1 Label", "defaultValue": "Total Revenue", "group": "Content" },
      "metric1Value": { "dataType": "text", "displayName": "Metric 1 Value", "defaultValue": "847500", "group": "Content" },
      "metric1Prefix": { "dataType": "text", "displayName": "Metric 1 Prefix", "defaultValue": "$", "group": "Content" },
      "metric2Label": { "dataType": "text", "displayName": "Metric 2 Label", "defaultValue": "Active Users", "group": "Content" },
      "metric2Value": { "dataType": "text", "displayName": "Metric 2 Value", "defaultValue": "12847", "group": "Content" },
      "metric3Label": { "dataType": "text", "displayName": "Metric 3 Label", "defaultValue": "Conversion Rate", "group": "Content" },
      "metric3Value": { "dataType": "text", "displayName": "Metric 3 Value", "defaultValue": "24.7", "group": "Content" },
      "metric3Suffix": { "dataType": "text", "displayName": "Metric 3 Suffix", "defaultValue": "%", "group": "Content" },
      "chartData": { "dataType": "text", "displayName": "Bar Chart Data (comma-separated)", "defaultValue": "45,72,58,89,64,91,77,83", "group": "Content" },
      "chartLabels": { "dataType": "text", "displayName": "Bar Chart Labels (comma-separated)", "defaultValue": "Jan,Feb,Mar,Apr,May,Jun,Jul,Aug", "group": "Content" },
      "progressValue": { "dataType": "text", "displayName": "Progress Ring Value", "defaultValue": "68", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background", "defaultValue": "#FFFFFF", "group": "Colors" },
      "cardBackground": { "dataType": "color", "displayName": "Card Background", "defaultValue": "#F8F9FA", "group": "Colors" },
      "primaryColor": { "dataType": "color", "displayName": "Primary Color", "defaultValue": "#495057", "group": "Colors" },
      "accentColor": { "dataType": "color", "displayName": "Accent Color", "defaultValue": "#2D7D3E", "group": "Colors" },
      "textColor": { "dataType": "color", "displayName": "Text Color", "defaultValue": "#212529", "group": "Colors" },
      "mutedColor": { "dataType": "color", "displayName": "Muted Text", "defaultValue": "#6C757D", "group": "Colors" },
      "borderColor": { "dataType": "color", "displayName": "Border Color", "defaultValue": "#E9ECEF", "group": "Colors" },
      "metricSize": { "dataType": "select", "displayName": "Metric Number Size", "defaultValue": "36", "options": ["28", "32", "36", "40", "48"], "group": "Typography" },
      "labelSize": { "dataType": "select", "displayName": "Label Size", "defaultValue": "13", "options": ["12", "13", "14", "15"], "group": "Typography" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config }) {
  const [animatedMetric1, setAnimatedMetric1] = useState(0);
  const [animatedMetric2, setAnimatedMetric2] = useState(0);
  const [animatedMetric3, setAnimatedMetric3] = useState(0);
  const [hoveredBar, setHoveredBar] = useState(null);
  const [progressOffset, setProgressOffset] = useState(283);

  const metric1Target = parseFloat(config?.metric1Value || '847500');
  const metric2Target = parseFloat(config?.metric2Value || '12847');
  const metric3Target = parseFloat(config?.metric3Value || '24.7');
  const progressValue = parseFloat(config?.progressValue || '68');

  const chartData = (config?.chartData || '45,72,58,89,64,91,77,83').split(',').map(v => parseFloat(v.trim()));
  const chartLabels = (config?.chartLabels || 'Jan,Feb,Mar,Apr,May,Jun,Jul,Aug').split(',').map(l => l.trim());
  const maxChartValue = Math.max(...chartData);

  useEffect(() => {
    const duration = 1500;
    const steps = 60;
    const stepDuration = duration / steps;

    const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

    let currentStep = 0;
    const interval = setInterval(() => {
      currentStep++;
      const progress = currentStep / steps;
      const easedProgress = easeOutCubic(progress);

      setAnimatedMetric1(Math.floor(metric1Target * easedProgress));
      setAnimatedMetric2(Math.floor(metric2Target * easedProgress));
      setAnimatedMetric3((metric3Target * easedProgress).toFixed(1));

      if (currentStep >= steps) {
        clearInterval(interval);
        setAnimatedMetric1(metric1Target);
        setAnimatedMetric2(metric2Target);
        setAnimatedMetric3(metric3Target.toFixed(1));
      }
    }, stepDuration);

    const circumference = 2 * Math.PI * 45;
    const offset = circumference - (progressValue / 100) * circumference;
    setTimeout(() => setProgressOffset(offset), 100);

    return () => clearInterval(interval);
  }, [metric1Target, metric2Target, metric3Target, progressValue]);

  const formatNumber = (num) => {
    return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  };

  return (
    <div className="data-dashboard" style={{
      backgroundColor: config?.backgroundColor || '#FFFFFF',
      padding: '32px',
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
      minHeight: '600px'
    }}>
      {/* Metrics Row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginBottom: '32px' }}>
        {/* Metric 1 */}
        <div style={{
          backgroundColor: config?.cardBackground || '#F8F9FA',
          border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
          borderRadius: '8px',
          padding: '24px'
        }}>
          <div style={{ fontSize: `${config?.labelSize || '13'}px`, color: config?.mutedColor || '#6C757D', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            {config?.metric1Label || 'Total Revenue'}
          </div>
          <div style={{ fontSize: `${config?.metricSize || '36'}px`, fontWeight: '500', color: config?.textColor || '#212529' }}>
            {config?.metric1Prefix || '$'}{formatNumber(animatedMetric1)}
          </div>
        </div>

        {/* Metric 2 */}
        <div style={{
          backgroundColor: config?.cardBackground || '#F8F9FA',
          border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
          borderRadius: '8px',
          padding: '24px'
        }}>
          <div style={{ fontSize: `${config?.labelSize || '13'}px`, color: config?.mutedColor || '#6C757D', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            {config?.metric2Label || 'Active Users'}
          </div>
          <div style={{ fontSize: `${config?.metricSize || '36'}px`, fontWeight: '500', color: config?.textColor || '#212529' }}>
            {formatNumber(animatedMetric2)}
          </div>
        </div>

        {/* Metric 3 */}
        <div style={{
          backgroundColor: config?.cardBackground || '#F8F9FA',
          border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
          borderRadius: '8px',
          padding: '24px'
        }}>
          <div style={{ fontSize: `${config?.labelSize || '13'}px`, color: config?.mutedColor || '#6C757D', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            {config?.metric3Label || 'Conversion Rate'}
          </div>
          <div style={{ fontSize: `${config?.metricSize || '36'}px`, fontWeight: '500', color: config?.textColor || '#212529' }}>
            {animatedMetric3}{config?.metric3Suffix || '%'}
          </div>
        </div>
      </div>

      {/* Charts Row */}
      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
        {/* Bar Chart */}
        <div style={{
          backgroundColor: config?.cardBackground || '#F8F9FA',
          border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
          borderRadius: '8px',
          padding: '24px'
        }}>
          <div style={{ fontSize: '16px', fontWeight: '500', color: config?.textColor || '#212529', marginBottom: '20px' }}>
            Monthly Performance
          </div>
          <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', height: '200px', gap: '8px' }}>
            {chartData.map((value, index) => {
              const heightPercent = (value / maxChartValue) * 100;
              const isHovered = hoveredBar === index;
              return (
                <div key={index} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                  <div
                    onMouseEnter={() => setHoveredBar(index)}
                    onMouseLeave={() => setHoveredBar(null)}
                    style={{
                      width: '100%',
                      height: `${heightPercent}%`,
                      backgroundColor: isHovered ? (config?.accentColor || '#2D7D3E') : (config?.primaryColor || '#495057'),
                      borderRadius: '4px 4px 0 0',
                      transition: 'all 200ms ease-out',
                      cursor: 'pointer',
                      opacity: isHovered ? 1 : 0.9,
                      animation: `barGrow 600ms ease-out ${index * 80}ms both`
                    }}
                  />
                  <div style={{ fontSize: '11px', color: config?.mutedColor || '#6C757D' }}>
                    {chartLabels[index]}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Progress Ring */}
        <div style={{
          backgroundColor: config?.cardBackground || '#F8F9FA',
          border: `1px solid ${config?.borderColor || '#E9ECEF'}`,
          borderRadius: '8px',
          padding: '24px',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center'
        }}>
          <div style={{ fontSize: '16px', fontWeight: '500', color: config?.textColor || '#212529', marginBottom: '20px' }}>
            Goal Progress
          </div>
          <div style={{ position: 'relative', width: '140px', height: '140px' }}>
            <svg width="140" height="140" style={{ transform: 'rotate(-90deg)' }}>
              <circle cx="70" cy="70" r="45" fill="none" stroke={config?.borderColor || '#E9ECEF'} strokeWidth="10" />
              <circle
                cx="70"
                cy="70"
                r="45"
                fill="none"
                stroke={config?.accentColor || '#2D7D3E'}
                strokeWidth="10"
                strokeDasharray="283"
                strokeDashoffset={progressOffset}
                strokeLinecap="round"
                style={{ transition: 'stroke-dashoffset 1000ms ease-out' }}
              />
            </svg>
            <div style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              fontSize: '32px',
              fontWeight: '500',
              color: config?.textColor || '#212529'
            }}>
              {progressValue}%
            </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes barGrow {
          from { transform: scaleY(0); opacity: 0; }
          to { transform: scaleY(1); opacity: 0.9; }
        }
      `}</style>
    </div>
  );
}

