      "textColor": { "dataType": "color", "defaultValue": "#171717", "group": "Colors" }
    }
  }
};

function Component({ config = {} }) {
  const projects = React.useMemo(() => {
    try {
      return JSON.parse(config?.projects || "[]");
    } catch { return []; }
  }, [config?.projects]);

  const bgColor = config?.backgroundColor || "#FFFFFF";
  const textColor = config?.textColor || "#171717";

  return (
    <div style={{
      backgroundColor: bgColor,
      color: textColor,
      padding: '120px 40px',
      fontFamily: 'Inter, sans-serif'
    }}>
      <div style={{ maxWidth: '1400px', margin: '0 auto' }}>
        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(12, 1fr)', 
          gap: '40px' 
        }}>
          {projects.map((project, i) => {
            // Asymmetric Layout Logic
            const isEven = i % 2 === 0;
            const colSpan = isEven ? 'span 7' : 'span 5';
            const startCol = isEven ? '1' : '8';
            const marginTop = i === 0 ? '0' : (isEven ? '120px' : '-120px');

            return (
              <div key={i} style={{
                gridColumn: window.innerWidth > 768 ? `${startCol} / ${colSpan}` : '1 / -1',
                marginTop: window.innerWidth > 768 ? marginTop : '60px',
                position: 'relative',
                group: 'project'
              }}>
                <div 
                  style={{
                    width: '100%',
                    paddingBottom: '120%', // Portrait aspect ratio
                    position: 'relative',
                    overflow: 'hidden',
                    marginBottom: '24px'
                  }}
                  onMouseEnter={e => {
                    e.currentTarget.querySelector('img').style.transform = 'scale(1.05)';
                    e.currentTarget.querySelector('.overlay').style.opacity = '1';
                  }}
                  onMouseLeave={e => {
                    e.currentTarget.querySelector('img').style.transform = 'scale(1)';
                    e.currentTarget.querySelector('.overlay').style.opacity = '0';
                  }}
                >
                  <img 
                    src={project.img} 
                    alt={project.title}
                    style={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      width: '100%',
                      height: '100%',
                      objectFit: 'cover',
                      transition: 'transform 0.6s cubic-bezier(0.22, 1, 0.36, 1)',
                      willChange: 'transform'
                    }}
                  />
                  <div className="overlay" style={{
                    position: 'absolute',
                    top: 0, left: 0, right: 0, bottom: 0,
                    backgroundColor: 'rgba(0,0,0,0.2)',
                    opacity: 0,
                    transition: 'opacity 0.4s ease'
                  }} />
                </div>

                <h3 style={{
                  fontSize: '32px',
                  fontWeight: '400',
                  margin: '0 0 8px 0',
                  letterSpacing: '-0.02em'
                }}>{project.title}</h3>
                <p style={{
                  fontSize: '14px',
                  textTransform: 'uppercase',
                  letterSpacing: '0.05em',
                  opacity: 0.6,
                  margin: 0
                }}>{project.cat}</p>
                <div style={{
                  height: '1px',
                  width: '100%',
                  backgroundColor: textColor,
                  marginTop: '24px',
                  opacity: 0.2
                }} />
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

