            }}>
              {stat.label}
            </p>
          </div>
        ))}
      </section>

      {/* About Section */}
      <section 
        id="about"
        ref={el => refs.current.about = el}
        style={{
          padding: '100px 80px',
          display: 'grid',
          gridTemplateColumns: '1fr 2fr',
          gap: '80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
      >
        <h2 className={visible.about ? 'fade-animate' : ''} style={{
          fontSize: '14px',
          fontWeight: 500,
          letterSpacing: '0.1em',
          color: secondaryText
        }}>
          {aboutTitle}
        </h2>
        <p className={visible.about ? 'fade-animate' : ''} style={{
          fontSize: 'clamp(20px, 2.5vw, 28px)',
          fontWeight: 400,
          lineHeight: 1.7,
          animationDelay: '0.1s'
        }}>
          {aboutText}
        </p>
      </section>

      {/* Services Section */}
      <section 
        id="services"
        ref={el => refs.current.services = el}
        style={{
          padding: '80px',
          backgroundColor: '#FAFAFA',
          borderTop: `1px solid ${borderColor}`,
          borderBottom: `1px solid ${borderColor}`
        }}
      >
        <div style={{ maxWidth: '1400px', margin: '0 auto' }}>
          <h2 className={visible.services ? 'fade-animate' : ''} style={{
            fontSize: '14px',
            fontWeight: 500,
            letterSpacing: '0.1em',
            color: secondaryText,
            marginBottom: '50px'
          }}>
            {servicesTitle}
          </h2>
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(3, 1fr)',
            gap: '40px'
          }}>
            {services.map((service, index) => (
              <div 
                key={index}
                className={visible.services ? 'fade-animate' : ''}
                style={{
                  animationDelay: `${0.1 + index * 0.1}s`
                }}
              >
                <span style={{
                  fontSize: '12px',
                  fontWeight: 400,
                  color: secondaryText,
                  display: 'block',
                  marginBottom: '16px'
                }}>
                  0{index + 1}
                </span>
                <p style={{
                  fontSize: '20px',
                  fontWeight: 400,
                  lineHeight: 1.5
                }}>
                  {service}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Clients Section */}
      <section 
        id="clients"
        ref={el => refs.current.clients = el}
        style={{
          padding: '80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
      >
        <h2 className={visible.clients ? 'fade-animate' : ''} style={{
          fontSize: '14px',
          fontWeight: 500,
          letterSpacing: '0.1em',
          color: secondaryText,
          marginBottom: '40px'
        }}>
          {clientsTitle}
        </h2>
        <div style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: '16px'
        }}>
          {clients.map((client, index) => (
            <span 
              key={index}
              className={visible.clients ? 'fade-animate' : ''}
              style={{
                padding: '12px 24px',
                border: `1px solid ${borderColor}`,
                borderRadius: '30px',
                fontSize: '15px',
                fontWeight: 400,
                animationDelay: `${0.05 + index * 0.05}s`
              }}
            >
              {client}
            </span>
          ))}
        </div>
      </section>

      {/* CTA Section */}
      <section 
        id="cta"
        ref={el => refs.current.cta = el}
        style={{
          padding: '120px 80px',
          backgroundColor: accentColor,
          color: backgroundColor,
          textAlign: 'center'
        }}
      >
        <h2 className={visible.cta ? 'stat-animate' : ''} style={{
          fontSize: 'clamp(28px, 4vw, 48px)',
          fontWeight: 300,
          marginBottom: '40px'
        }}>
          {ctaTitle}
        </h2>
        <button 
          className={visible.cta ? 'stat-animate' : ''}
          style={{
            backgroundColor: backgroundColor,
            color: accentColor,
            border: 'none',
            padding: '18px 48px',
            fontSize: '15px',
            fontWeight: 500,
            cursor: 'pointer',
            transition: 'transform 0.3s ease',
            animationDelay: '0.1s'
          }}
          onMouseEnter={e => e.target.style.transform = 'translateY(-3px)'}
          onMouseLeave={e => e.target.style.transform = 'translateY(0)'}
        >
          {ctaButton}
        </button>
      </section>
    </div>
  );
}

